mapper.update:
update cms_registration_seat_invitation
set status = #{toStatus}, update_time = #{now}, version = version + 1
where id = #{id} and status = #{fromStatus}

update cms_registration_seat_invitation
set status = 3, update_time = #{now}, version = version + 1
where registration_id = #{registrationId} and status = 0 and expires_at <= #{now}

mapper.select:
select count(*) from cms_registration_seat_invitation
where registration_id = #{registrationId} and invitee_member_id = #{inviteeMemberId}
  and status = 1
